// Some portions generated by Co-Pilot
import { useTranslations } from "next-intl";
import { getFormattedAuthorData } from "@/utils/authors";

interface NewsEmptyStateProps {
  tag?: string;
  author?: string;
  source?: string;
}

export default function NewsEmptyState({
  tag,
  author,
  source,
}: NewsEmptyStateProps) {
  const t = useTranslations("ModernPages.news");
  const formattedAuthor = author
    ? getFormattedAuthorData(author).name
    : undefined;

  const formattedSource = source
    ? source.replace(/-/g, " ").replace(/\b\w/g, (c) => c.toUpperCase())
    : undefined;

  return (
    <div className="mx-auto my-8 flex max-w-7xl flex-col items-center justify-center rounded-2xl border border-white/10 bg-white/[0.025] px-6 py-12 text-center">
      <h2 className="text-2xl font-semibold text-white mb-4">
        {t("no-results")}
      </h2>

      <p className="text-white/70 max-w-md">{t("empty")}</p>

      <div className="mt-6 flex gap-2 flex-wrap justify-center">
        {tag && (
          <span className="px-3 py-1 rounded-full bg-purple-500/20 text-purple-300 text-sm">
            {t("tag")}: {tag}
          </span>
        )}
        {formattedAuthor && (
          <span className="px-3 py-1 rounded-full bg-purple-500/20 text-purple-300 text-sm">
            {t("author")}: {formattedAuthor}
          </span>
        )}
        {formattedSource && (
          <span className="px-3 py-1 rounded-full bg-purple-500/20 text-purple-300 text-sm">
            {t("source")}: {formattedSource}
          </span>
        )}
      </div>

      <p className="mt-6 text-white/50">{t("empty-description")}</p>
    </div>
  );
}
